  // bt[0]=9 >= num_pages=8 -> the complete-pool write must throw.
  EXPECT_THROW(dsa_kpool_decode_update_cpu(1, 1, 128, 1, 2, 1, 1, 8, key.data(),
                                           slot_score.data(), tail_k.data(),
                                           tail_score.data(), ape.data(),
